def so_dong_xe(p):
    o = orders(p)
    xe = o["vehicle"].astype(str).str.lower().unique()
    return len(xe)

def so_bien_so(p):
    o = orders(p)
    if o.empty:
        raise Unanswerable("không có đơn trong kỳ")
    plate = o["plate"].dropna().astype(str).str.lower()
    return len(plate.unique())

